/* Reproducible, development-only vendor build. Both renderers share the same Three.js core. */
'use strict';
const fs=require('node:fs'),path=require('node:path'),{pathToFileURL}=require('node:url');
const esbuild=require('esbuild');
async function build(){
  const root=path.resolve(__dirname,'../..'),out=path.join(root,'game3d/lib');
  const common={bundle:true,format:'iife',platform:'browser',target:'es2020',supported:{'template-literal':false},minify:true,legalComments:'eof',
    banner:{js:'/*! Three.js r187, MIT. Generated by tools/vendor/build.cjs; see THREE-LICENSE.txt. */'}};
  await esbuild.build({...common,entryPoints:[path.join(__dirname,'three-entry.js')],globalName:'THREE',outfile:path.join(out,'three.min.js')});
  const core=await import(pathToFileURL(path.join(__dirname,'node_modules/three/build/three.core.js')));
  const sharedCore={name:'shared-three-core',setup(b){
    b.onResolve({filter:/three\.core\.js$/},()=>({path:'core',namespace:'shared-three'}));
    b.onLoad({filter:/.*/,namespace:'shared-three'},()=>({contents:Object.keys(core).map(k=>'export const '+k+'=globalThis.THREE.'+k+';').join('\n'),loader:'js'}));
  }};
  await esbuild.build({...common,entryPoints:[path.join(__dirname,'webgpu-entry.js')],globalName:'WdfzWebGPU',
    plugins:[sharedCore],outfile:path.join(out,'three-webgpu.min.js')});
  fs.copyFileSync(path.join(__dirname,'node_modules/three/LICENSE'),path.join(out,'THREE-LICENSE.txt'));
}
build().catch(e=>{console.error(e);process.exitCode=1;});
